PRAGMA page_size=1024; PRAGMA auto_vacuum=incremental; VACUUM; CREATE TABLE t1(a PRIMARY KEY,b); WITH animals(a) AS (VALUES('alligator'),('angelfish'),('ant'),('antelope'),('ape'),('baboon'),('badger'),('bear'),('beetle'),('bird'),('bison')) INSERT INTO t1(a) SELECT a FROM animals; UPDATE t1 SET b=replace(hex(zeroblob(1000)),'00','x')||replace(hex(zeroblob(1000)),'00','y')||replace(hex(zeroblob(1000)),'00','z')||replace(hex(zeroblob(1000)),'00','w');